cpu=max(os.sched_getaffinity(0))
versions=['baseline','candidate']
hashes={v:hashlib.sha256((root/(v+'.exe')).read_bytes()).hexdigest() for v in versions}
corpus=Path('/home/jtenner/Projects/starshine-mb/.tmp/runtime-compare-20261011/wago-source/corpus/workloads')
inputs=[('micropython',root/'micropython-input.wasm','--optimize-instructions'),('fannkuch',corpus/'compute/fannkuch.wasm','--optimize-instructions'),('sha256',corpus/'compute/sha256.wasm','--optimize-instructions'),('sqlite3',corpus/'applications/sqlite3/sqlite3.wasm','--optimize-instructions'),('branch-call',root/'fixtures/branch-call.wasm','--remove-unused-brs')]
