 samples=[];output_hashes={}
 for round in range(-2,9):
  for version in versions if round%2==0 else versions[::-1]:
   out=root/f'cost-{name}-{version}.wasm';rss_file=root/'cost-rss.txt'
   cmd=[str(root/(version+'.exe')),str(source),flag,'-o',str(out)]
   start=time.perf_counter_ns()
   with tempfile.TemporaryFile() as errors:
