 rows.append({'input':name,'inputHash':hashlib.sha256(source.read_bytes()).hexdigest(),'pass':flag,'outputHashes':output_hashes,'samples':samples,'summary':summary,'percentChange':100*(summary['candidate']['medianMs']/summary['baseline']['medianMs']-1)})
