import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import os from 'node:os';
import assert from 'node:assert/strict';
import { WASI } from 'node:wasi';
const root=path.dirname(new URL(import.meta.url).pathname);
const inputDir='/home/jtenner/Projects/starshine-mb/.tmp/runtime-compare-20261011/wago-source/corpus/workloads/applications/micropython/inputs';
const versions=['baseline','candidate'];
const mode=process.argv.includes('--same')?'same-binary-control':process.argv.includes('--reverse-compile')?'reverse-compile':'default';
const files=versions.map(v=>path.join(root,`micropython-${mode==='same-binary-control'?'baseline':v}.wasm`));
const modules=[];
for(const i of mode==='reverse-compile'?[1,0]:[0,1]) modules[i]=new WebAssembly.Module(fs.readFileSync(files[i]));
let serial=0;
function run(index) {
 const output=path.join(root,`micropython-stdout-${serial++}.txt`), fd=fs.openSync(output,'w');
 const wasi=new WASI({version:'preview1',args:['micropython','/program.py'],env:{},preopens:{'/':inputDir},returnOnExit:true,stdout:fd,stderr:fd});
 let hostCalls=0;
 const instance=new WebAssembly.Instance(modules[index],{wasi_snapshot_preview1:wasi.wasiImport,micropython_wasm:{host_result_cap(){return 1024},host_call(){hostCalls++;throw new Error('unexpected host_call')}}});
 const start=process.hrtime.bigint();
 const exit=wasi.start(instance);
 const ms=Number(process.hrtime.bigint()-start)/1e6;
 fs.closeSync(fd);
 const stdout=fs.readFileSync(output);
 assert.equal(exit,0);assert.equal(hostCalls,0);
 assert.equal(crypto.createHash('sha256').update(stdout).digest('hex'),'f6d55657e93a308383869175bd299ef355d0e1b95fe32475027f060fb9aef8cd');
 return ms;
}
for(let warmup=0;warmup<3;warmup++) for(let i=0;i<2;i++) run(i);
const samples=[];
for(let round=0;round<11;round++) for(const index of round%2?[1,0]:[0,1]) samples.push({round,version:versions[index],executionMs:run(index)});
const median=values=>[...values].sort((a,b)=>a-b)[Math.floor(values.length/2)];
const summary=Object.fromEntries(versions.map(v=>{const xs=samples.filter(s=>s.version===v).map(s=>s.executionMs),m=median(xs);return [v,{medianMs:m,madMs:median(xs.map(x=>Math.abs(x-m))),minMs:Math.min(...xs),maxMs:Math.max(...xs)}]}));
const report={mode,runtime:process.version,cpu:os.cpus()[0].model,arch:process.arch,warmup:3,measuredRounds:11,outputHash:'f6d55657e93a308383869175bd299ef355d0e1b95fe32475027f060fb9aef8cd',inputHashes:files.map(file=>crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex')),samples,summary,percentChange:100*(summary.candidate.medianMs/summary.baseline.medianMs-1)};
fs.writeFileSync(path.join(root,mode==='default'?'micropython-runtime.json':`micropython-runtime-${mode}.json`),JSON.stringify(report,null,2));
console.log(JSON.stringify({mode,summary,percentChange:report.percentChange}));

