import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
const root=path.dirname(new URL(import.meta.url).pathname);
const rows=[];
function observation(file,args,condition=1,hostTrap=false) {
 let calls=0;
 const module=new WebAssembly.Module(fs.readFileSync(file));
 const instance=new WebAssembly.Instance(module,{m:{c(){calls++;if(hostTrap)throw new Error('host-trap');return condition;}}});
 let result;
 try {result={kind:'return',value:instance.exports.run(...args)};}
 catch(e){result={kind:e instanceof WebAssembly.RuntimeError?'wasm-trap':'host-trap',message:e.message};}
 let memory=null;
 if(instance.exports.memory) memory={bytes:[...new Uint8Array(instance.exports.memory.buffer).subarray(0,8)],length:instance.exports.memory.buffer.byteLength};
 return {result,calls,memory};
}
for(const name of fs.readdirSync(path.join(root,'fixtures')).filter(n=>n.endsWith('.wasm'))) {
 const stem=name.slice(0,-5), paths=['fixtures','baseline','candidate'].map(dir=>path.join(root,dir,name));
 let argumentsList;
 if(stem.startsWith('i64-')) argumentsList=[0n,1n,-1n,-9223372036854775808n,9223372036854775807n,0x0123456789abcdefn].map(v=>[v]);
 else if(stem.startsWith('i32-')) argumentsList=[0,1,-1,-2147483648,2147483647,0x12345678].map(v=>[v]);
 else if((stem==='tee-trap'||stem==='raw-trap')) argumentsList=[[9,2],[9,0],[-2147483648,-1]];
 else if(stem==='tee-invalidating') argumentsList=[[1,2],[-1,0],[0,-1]];
 else if(stem==='tee-grow') argumentsList=[[0],[1],[2],[-1]];
 else if(stem==='tee-trunc') argumentsList=[[0],[1.5],[NaN],[Infinity],[2147483648],[-2147483649]];
 else if(stem==='float-nan') argumentsList=[[NaN],[0],[Infinity],[-0]];
 else if(stem==='branch-load'||stem==='ordered-load-store') argumentsList=[[0],[65533],[65536],[-1]];
 else if(stem==='branch-nested') argumentsList=[[0],[1],[-1]];
 else argumentsList=[[]];
 let observations=0;
 for(const args of argumentsList) for(const condition of stem.includes('call')?[0,1,-1]:[1]) for(const hostTrap of stem.includes('call')?[false,true]:[false]) {
  const values=paths.map(file=>observation(file,args,condition,hostTrap));
  assert.deepEqual(values[1],values[0],`${stem}:baseline`);
  assert.deepEqual(values[2],values[0],`${stem}:candidate`);
  observations++;
 }
 rows.push({fixture:stem,observations});
}
fs.writeFileSync(path.join(root,'runtime-check.json'),JSON.stringify({runtime:process.version,rows,total:rows.reduce((s,r)=>s+r.observations,0)},null,2));
console.log(JSON.stringify({fixtures:rows.length,observations:rows.reduce((s,r)=>s+r.observations,0),status:'equal'}));
